'use strict';
const navigation=document.getElementById('nav'),toggle=document.getElementById('menu');
if(toggle&&navigation){toggle.addEventListener('click',()=>{const open=navigation.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');toggle.textContent=open?'×':'☰'});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){navigation.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation');toggle.textContent='☰';toggle.focus()}})}
const parameters=new URLSearchParams(location.search),industryField=document.querySelector('[name="industry"]');
if(industryField&&[...industryField.options].some(o=>o.value===parameters.get('industry')))industryField.value=parameters.get('industry');
document.querySelectorAll('[data-enquiry]').forEach(form=>{
 form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const labels={name:'Name',email:'Email',company:'Company / role',equipment:'Equipment',serial:'Model / serial',industry:'Industry',market:'Market',message:'Message'};const type=form.dataset.enquiry;const subject=type==='support'?'Technical support enquiry':type==='careers'?'Careers contact enquiry':'Project enquiry';const body=[...data.entries()].filter(([,v])=>String(v).trim()).map(([k,v])=>(labels[k]||k)+': '+String(v).trim()).join('\n\n');const result=form.querySelector('.draft-result');form.querySelector('.draft-body').value=subject+'\n\n'+body;form.querySelector('.draft-mail').href='mailto:'+form.dataset.recipient+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);result.hidden=false;result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});});
 form.querySelector('.copy-draft').addEventListener('click',async()=>{const field=form.querySelector('.draft-body'),status=form.querySelector('.copy-status');try{await navigator.clipboard.writeText(field.value);status.textContent='Draft copied. Paste it into your email app.'}catch{field.select();status.textContent='Select and copy the draft text above.'}});
});
